import {createDemo,createProject,createSound,startVersion,finishVersion,deleteVersion,restoreVersion,activeVersions,setFinal,recoverJobs,kinds} from './model.mjs';
const $=s=>document.querySelector(s), key='music-room-sound-first-prototype-v1';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state;try{state=JSON.parse(localStorage.getItem(key));if(state?.schema!==1||!state.projects?.length)state=null;}catch{}
state=recoverJobs(state??createDemo());
let projectId=state.projects[0].id,soundId=state.projects[0].sounds[0]?.id,versionId,filter='all',compare=[],parentId,toastTimer,playingId,waveEpoch=0;
const references=new Map(),files=new Map(),waves=new Map(),audio=$('#audio'),dialog=$('#dialog');
const project=()=>state.projects.find(p=>p.id===projectId),sound=()=>project().sounds.find(s=>s.id===soundId);
const version=()=>activeVersions(sound()??{versions:[]}).find(v=>v.id===versionId);
const time=n=>`${Math.floor((n||0)/60).toString().padStart(2,'0')}:${Math.floor((n||0)%60).toString().padStart(2,'0')}`;
const src=v=>v?.imported==='midi'?undefined:v?.audio||files.get(v?.id)?.url;
const icon={music:'♫',clip:'≋',speech:'“'};
function save(){try{localStorage.setItem(key,JSON.stringify(state));}catch{toast('浏览器存储空间不足，本次改动仅在当前页面保留。');}}
function toast(message,undo){clearTimeout(toastTimer);$('#toast').hidden=false;$('#toast').replaceChildren(document.createTextNode(message));if(undo){const b=document.createElement('button');b.textContent='撤销';b.onclick=()=>{undo();$('#toast').hidden=true;};$('#toast').append(b);}toastTimer=setTimeout(()=>$('#toast').hidden=true,8000);}
function stop(){audio.pause();playingId=undefined;}
function resetSelection(){stop();audio.loop=false;compare=[];parentId=undefined;filter='all';versionId=sound()?.finalId??activeVersions(sound()??{versions:[]}).at(-1)?.id;}
function render(){
  const p=project(),s=sound();
  $('#projects').innerHTML=state.projects.map(item=>`<button class="project-link ${item.id===p.id?'active':''}" data-action="project" data-id="${item.id}" aria-current="${item.id===p.id?'page':'false'}"><span>▧</span><span>${esc(item.title)}<small>${item.sounds.length} 个声音</small></span></button>`).join('');
  if(s&&!version())versionId=activeVersions(s).at(-1)?.id;
  $('#main').innerHTML=`<header class="project-header"><div><div class="eyebrow">我的项目 <span>/</span> 创作空间</div><h1>${esc(p.title)}</h1><p>${esc(p.description||'从一个声音开始。每次尝试，都会留在这里。')}</p></div><button class="secondary" data-action="deliverables">项目成品 <span>${p.sounds.filter(s=>s.finalId).length}</span> ↗</button></header>
  <section class="sounds-section" aria-label="项目中的声音"><div class="section-label"><h2>这个项目的声音 <span>${p.sounds.length}</span></h2><div><button class="quiet" data-action="import">↥ 导入文件</button><button class="quiet accent" data-action="new-sound">＋ 新声音</button></div></div>
  <div class="sound-tabs">${p.sounds.map(item=>`<button class="sound-tab ${item.id===s?.id?'selected':''}" data-action="sound" data-id="${item.id}" aria-pressed="${item.id===s?.id}"><span class="sound-icon ${item.kind}">${icon[item.kind]}</span><span><strong>${esc(item.title)}</strong><small>${kinds[item.kind]}${item.kind==='music'?' · '+(item.vocal==='vocal'?'带人声':'纯音乐'):''} · ${activeVersions(item).length?`${activeVersions(item).length} 个版本`:'还没有版本'}</small></span>${item.finalId?'<span class="tiny-dot" title="已选成品"></span>':''}</button>`).join('')}${!p.sounds.length?'<button class="empty-sound" data-action="new-sound">＋ 创建第一个声音</button>':''}</div></section>
  ${s?`<div class="creative-grid"><section class="listening-space" aria-label="试听与版本"><div class="sound-heading"><div><div class="eyebrow">${kinds[s.kind]}${s.kind==='music'?' / '+(s.vocal==='vocal'?'带人声':'纯音乐'):''}</div><h2>${esc(s.title)}</h2></div><span class="subtle">${s.kind==='speech'?'IndexTTS 2.0':esc(s.duration)+' · 目标时长'}</span></div>${playerMarkup(s)}${versionsMarkup(s)}</section>${composerMarkup(s)}</div>`:`<section class="empty-project"><span class="empty-symbol">♫</span><h2>这个项目，会是什么声音？</h2><p>一段 riff、一首歌，或一句旁白。先做一个，听过再继续。</p><button class="primary" data-action="new-sound">＋ 创建第一个声音</button><button class="quiet" data-action="import">已有音频或 MIDI？导入文件</button></section>`}
  <footer class="project-footer">${s?'每次尝试单独保存，旧版本始终保留。':'一个项目可以容纳多个声音。'}<button class="quiet" data-action="trash">回收站${s?` · ${s.versions.filter(v=>v.deleted).length}`:''}</button></footer>`;
  if(s){$('#voice-reference')?.addEventListener('change',e=>{const f=e.target.files[0];if(!f)return;if(!f.type.startsWith('audio/')||!f.size){toast('请选择非空音频文件。');return;}references.set(s.id,f);$('#voice-reference-status').textContent=`已选：${f.name} · 仅本页可用`;});$('#prompt').addEventListener('input',e=>{s.draft=e.target.value;save();});$('#script')?.addEventListener('input',e=>{s.script=e.target.value;save();});$('#composer').addEventListener('submit',generate);$('#seek')?.addEventListener('input',e=>{if(playingId!==versionId)loadAudio(version());audio.currentTime=Number(e.target.value);updatePlayback();});drawWave(version());updatePlayback();}
}
function playerMarkup(s){const v=version();if(!v)return `<div class="player-empty"><span>${icon[s.kind]}</span><h3>第一个版本，从你的描述开始。</h3><p>${s.kind==='speech'?'添加参考声音，再填写要朗读的文字。':'在右侧描述你想听到的感觉。'}</p></div>`;
  const playable=!!src(v),done=v.status==='done',status={running:'正在生成',done:playable?'可试听':'演示结果',failed:'生成失败',cancelled:'已取消'}[v.status];
  return `<div class="player-card"><div class="player-top"><span><strong>V${v.number}</strong> <span class="badge ${playable?'green':''}">${status}</span>${s.finalId===v.id?'<span class="badge green">✓ 成品</span>':''}</span><button class="quiet" data-action="details">版本详情 ↗</button></div>
  <div class="wave-area">${playable?'<canvas id="wave" aria-label="音频波形"></canvas>':`<div class="no-audio ${v.status==='running'?'pending':''}"><span>${v.status==='running'?'◌':v.status==='failed'?'!':'♫'}</span><p>${v.status==='running'?'正在演示生成过程，可以继续浏览其他声音。':v.error??(v.imported==='midi'?'已导入 MIDI 参考文件，尚未合成音频。':v.imported==='audio'?'原型不跨刷新保留导入文件，请重新导入音频。':done?'流程演示已完成，未生成真实音频。':'本次生成已取消，创作要求已保留。')}</p></div>`}</div>
  <div class="player-controls"><button class="play" data-action="play" aria-label="播放当前版本" ${playable?'':'disabled'}>▶</button><span class="play-clock"><span id="elapsed">00:00</span> <span>/ ${playable?time(v.duration):'--:--'}</span></span><input id="seek" type="range" aria-label="播放进度" min="0" max="${v.duration||1}" step="0.1" value="0" ${playable?'':'disabled'}><button class="quiet" data-action="loop" aria-pressed="${audio.loop}" ${playable?'':'disabled'}>循环</button></div>
  <p class="player-caption">${esc(v.note??'')}</p>
  ${done?`<div class="version-actions"><button class="secondary ${v.kept?'is-kept':''}" data-action="keep" data-id="${v.id}">${v.kept?'★ 已留作灵感':'☆ 保留灵感'}</button><button class="secondary" data-action="final" data-id="${v.id}">${s.finalId===v.id?'✓ 已选作成品':'选作成品'}</button><button class="quiet accent" data-action="iterate" data-id="${v.id}">修改这版</button><button class="quiet" data-action="process">继续加工 ↗</button>${playable?`<a class="quiet" href="${esc(src(v))}" download="${esc(s.title)}-V${v.number}.${v.imported?'audio':'wav'}">${v.duration===20?'下载原始整曲':'↓ 下载音频'}</a>`:''}</div>`:''}</div>`;
}
function versionsMarkup(s){const all=activeVersions(s),vs=all.filter(v=>filter!=='kept'||v.kept).slice().reverse();return `<div class="versions-heading"><h3>版本 <span>${all.length}</span></h3><div class="filter" role="group" aria-label="版本筛选"><button data-action="filter" data-id="all" aria-pressed="${filter==='all'}">全部</button><button data-action="filter" data-id="kept" aria-pressed="${filter==='kept'}">已留灵感</button></div></div>
  ${all.length?`<p class="version-hint">勾选两版，听听哪一版更合适。<button class="quiet accent" data-action="compare" ${compare.length===2?'':'disabled'}>比较${compare.length?`（${compare.length}/2）`:''} ↗</button></p>`:''}
  <div class="version-list">${vs.map(v=>`<article class="version-row ${v.id===versionId?'selected':''}"><input type="checkbox" aria-label="比较 V${v.number}" data-compare="${v.id}" ${compare.includes(v.id)?'checked':''} ${v.status!=='done'?'disabled':''}><button class="version-select" data-action="version" data-id="${v.id}" aria-pressed="${v.id===versionId}"><span><strong>V${v.number}</strong>${v.kept?'<span class="star">★</span>':''}${s.finalId===v.id?'<span class="final-label">成品</span>':''}<small>${v.status==='done'?(src(v)?time(v.duration):v.imported?'MIDI 参考':'演示结果'):{running:'生成中…',failed:'失败 · 可重试',cancelled:'已取消'}[v.status]}</small></span><p>${esc(v.prompt||v.note)}</p>${v.parentId?`<small>基于 V${s.versions.find(x=>x.id===v.parentId)?.number??'?'}${s.versions.find(x=>x.id===v.parentId)?.deleted?'（已删除）':''}</small>`:''}</button><div class="row-end">${v.status==='running'?`<button class="quiet" data-action="cancel" data-id="${v.id}">取消</button>`:`<details class="row-menu"><summary aria-label="V${v.number} 更多操作">···</summary><div>${v.status==='done'?`<button data-action="iterate" data-id="${v.id}">基于这版修改</button><button data-action="keep" data-id="${v.id}">${v.kept?'取消保留灵感':'保留灵感'}</button>`:`<button data-action="retry" data-id="${v.id}">重试</button>`}<button class="danger" data-action="delete" data-id="${v.id}">删除版本</button></div></details>`}</div></article>`).join('')||`<p class="empty-versions">${filter==='kept'?'还没有保留的灵感。喜欢哪一版，点一下 ☆。':'生成结果会按版本出现在这里。'}</p>`}</div>`;}
function composerMarkup(s){return `<aside class="composer-panel" aria-label="创作要求"><div class="composer-title"><span class="spark">✳</span><h2>${activeVersions(s).length?'再试一个版本':'做出第一个版本'}</h2></div><p class="composer-subtitle">把想法说清楚，然后听听看。</p><form id="composer">${s.kind==='speech'?`<label for="voice-reference">参考声音</label><input id="voice-reference" type="file" accept="audio/*"><p id="voice-reference-status" class="field-note">${references.has(s.id)?`已选：${esc(references.get(s.id).name)} · 仅本页可用`:'添加一段参考音频，确定说话的音色。原型刷新后需重新选择。'}</p>`:''}<label for="prompt">${s.kind==='speech'?'情绪描述（可选）':'你想要什么样的声音？'}</label><textarea id="prompt" ${s.kind==='speech'?'':'required'} maxlength="8000" rows="${s.kind==='speech'?3:7}" placeholder="${s.kind==='speech'?'例如：平静、温暖。留空时沿用参考声音的情绪。':'比如：雨天散步的感觉，温暖的钢琴，轻一点，不要太满。'}">${esc(s.draft)}</textarea>${s.kind==='speech'||s.vocal==='vocal'?`<label class=script-label for=script>${s.kind==='speech'?'要说的文字':'歌词'}</label><textarea id=script required rows=4 placeholder="${s.kind==='speech'?'输入需要朗读的文字':'输入要演唱的歌词'}">${esc(s.script??'')}</textarea>`:''}${parentId?`<div class="based-on">基于 V${s.versions.find(v=>v.id===parentId)?.number} 继续修改 <button type="button" class="quiet" data-action="clear-parent">取消</button></div>`:''}
  <div class="composer-setting"><span>${s.kind==='speech'?'IndexTTS 2.0':kinds[s.kind]}</span><span>${s.kind==='speech'?'待接入 · 流程演示':esc(s.duration)}</span></div><details class="more-settings"><summary>更多设置</summary><label for="method">创作方式</label><select id="method"><option value="model">生成模型（流程演示）</option><option value="agent">交给 Agent 创作</option></select><label for="outcome">原型演示情境</label><select id="outcome"><option value="done">生成完成</option><option value="failed">生成失败与重试</option></select><p>正式产品只展示当前声音类型可用的模型；连接和安装在设置中完成。</p></details><button type="submit" class="primary generate">✳ 演示生成新版本</button><p class="demo-note">本原型不调用模型，不消耗额度。新版本不会覆盖已有版本。</p></form><div class="composer-tip"><span>小提示</span><p>${s.kind==='speech'?'参考声音决定音色，正文决定说什么；情绪可以单独调整。':'喜欢某个版本的一部分？先保留灵感，再基于它继续修改。'}</p></div></aside>`;}
function showDialog(title,content,wide=false){dialog.className=wide?'wide':'';dialog.innerHTML=`<div class="dialog-header"><h2>${title}</h2><button class="quiet close" data-action="close" aria-label="关闭">×</button></div>${content}`;if(!dialog.open)dialog.showModal();}
function newSoundDialog(){showDialog('想做一个什么声音？',`<form id="new-sound-form"><div class="type-picker">${Object.entries(kinds).map(([id,label],i)=>`<label><input type="radio" name="kind" value="${id}" ${i?'':'checked'}><span><b>${icon[id]}</b><strong>${label}</strong><small>${{clip:'riff、间奏、短配乐',music:'一首歌或一首器乐',speech:'旁白、朗读、对白'}[id]}</small></span></label>`).join('')}</div><label for="sound-title">给这个声音起个名字</label><input id="sound-title" maxlength="120" required placeholder="例如：开场吉他 riff"><div id="type-options"></div><div class="dialog-bottom"><button type="button" class="quiet" data-action="close">取消</button><button class="primary" type="submit">开始创作 →</button></div></form>`);
  const update=()=>{const kind=dialog.querySelector('[name=kind]:checked').value;$('#type-options').innerHTML=(kind==='music'?'<label for="vocal">人声</label><select id="vocal"><option value="instrumental">纯音乐</option><option value="vocal">带人声的歌曲</option></select>':'')+`<label for="target-duration">${kind==='speech'?'语音长度':'大约多长？'}</label><select id="target-duration">${(kind==='clip'?['20 秒','30 秒','自由长度']:kind==='music'?['3 分钟','5 分钟','自由长度']:['随文本自然生成']).map(x=>`<option>${x}</option>`).join('')}</select><p class="field-note">${kind==='speech'?'使用 IndexTTS 2.0；本版不提供精确时长或语速控制。':'这是创作目标，生成结果的实际时长可能不同。'}</p>`;};update();dialog.querySelectorAll('[name=kind]').forEach(el=>el.onchange=update);
  $('#new-sound-form').onsubmit=e=>{e.preventDefault();const s=createSound(project(),{title:$('#sound-title').value,kind:dialog.querySelector('[name=kind]:checked').value,vocal:$('#vocal')?.value,duration:$('#target-duration').value});soundId=s.id;resetSelection();save();dialog.close();render();$('#prompt').focus();};
}
function generate(e){e.preventDefault();const s=sound(),prompt=$('#prompt').value.trim();if(!prompt&&s.kind!=='speech'){$('#prompt').focus();return;}s.draft=prompt;const script=$('#script')?.value.trim()??'';s.script=script;const request=script?`${prompt}\n\n${s.kind==='speech'?'朗读正文':'歌词'}：\n${script}`:prompt;
  if($('#method').value==='agent'){showDialog('交给 Agent 创作',`<p>复制下面的要求，交给你正在使用的 Agent。拿到音频或 MIDI 后，用「导入文件」放回这个声音。</p><textarea id="agent-brief" rows="10" readonly>${esc(`项目：${project().title}\n声音：${s.title}（${kinds[s.kind]}）\n目标：${s.duration}\n${parentId?'基于版本：'+parentId+'\n':''}创作要求：${request}\n请交付音频，或适用于乐器演奏的 MIDI。不要覆盖旧版本。`)}</textarea><button class="primary" data-action="copy-brief">复制创作要求</button>`);return;}
  if(s.kind==='speech'&&!references.has(s.id)){toast('请先添加参考声音。');$('#voice-reference').focus();return;}
  stop();const outcome=$('#outcome').value,pid=projectId,sid=s.id,v=startVersion(s,request,parentId);v.description=prompt;v.script=script;if(s.kind==='speech'){v.engine='IndexTTS 2.0';v.referenceName=references.get(s.id).name;}parentId=undefined;versionId=v.id;filter='all';save();render();
  setTimeout(()=>{finishVersion(state,pid,sid,v.id,outcome);save();if(projectId===pid&&soundId===sid)render();toast(`${s.title} · V${v.number} ${v.status==='done'?'演示完成':v.status==='failed'?'生成失败（演示）':'已取消'}`);},2300);
}
function loadAudio(v){if(!src(v))return;audio.src=src(v);playingId=v.id;audio.currentTime=0;}
async function play(v=version()){if(!src(v))return;if(playingId!==v.id)loadAudio(v);if(audio.paused){if(audio.currentTime>=v.duration)audio.currentTime=0;try{await audio.play();}catch{toast('音频未能播放，请确认本地文件可用后重试。');}}else audio.pause();updatePlayback();}
function updatePlayback(){const v=version(),current=playingId===v?.id?audio.currentTime:0;if($('#elapsed'))$('#elapsed').textContent=time(current);if($('#seek'))$('#seek').value=current;
  const b=$('[data-action=play]');if(b){const on=playingId===v?.id&&!audio.paused;b.textContent=on?'Ⅱ':'▶';b.setAttribute('aria-label',on?'暂停当前版本':'播放当前版本');}
  dialog.querySelectorAll('[data-action=compare-play]').forEach(b=>{const on=playingId===b.dataset.id&&!audio.paused;b.textContent=on?'Ⅱ 暂停':'▶ 试听';});
}
audio.addEventListener('timeupdate',()=>{const v=state.projects.flatMap(p=>p.sounds).flatMap(s=>s.versions).find(v=>v.id===playingId);if(v&&audio.currentTime>=v.duration){if(audio.loop){audio.currentTime=0;}else audio.pause();}updatePlayback();});
audio.addEventListener('ended',updatePlayback);audio.addEventListener('error',()=>{if(playingId)toast('无法读取音频。请重新导入文件或检查本地服务。');});
async function drawWave(v){const canvas=$('#wave'),epoch=++waveEpoch;if(!canvas||!src(v))return;
  try{let peaks=waves.get(src(v));if(!peaks){const response=await fetch(src(v));if(!response.ok)throw Error();const context=new AudioContext();let decoded;try{decoded=await context.decodeAudioData(await response.arrayBuffer());}finally{await context.close();}const data=decoded.getChannelData(0),count=900,step=Math.max(1,Math.floor(data.length/count));peaks={duration:decoded.duration,values:Array.from({length:count},(_,i)=>{let max=0;for(let j=i*step;j<Math.min(data.length,(i+1)*step);j+=24)max=Math.max(max,Math.abs(data[j]));return max;})};waves.set(src(v),peaks);}
    if(epoch!==waveEpoch)return;const w=canvas.clientWidth,h=canvas.clientHeight;if(!w||!h)return;canvas.width=w*devicePixelRatio;canvas.height=h*devicePixelRatio;const c=canvas.getContext('2d');c.scale(devicePixelRatio,devicePixelRatio);const n=Math.floor(w/5),visible=peaks.values.slice(0,Math.max(1,Math.ceil(peaks.values.length*v.duration/peaks.duration))),max=Math.max(...visible,.01);for(let i=0;i<n;i++){const height=Math.max(3,visible[Math.floor(i*visible.length/n)]/max*(h-20));c.fillStyle='#8dab97';c.beginPath();c.roundRect(i*5,(h-height)/2,2.8,height,2);c.fill();}
  }catch{if(epoch===waveEpoch&&canvas.parentElement)canvas.parentElement.innerHTML='<p class="subtle">暂时无法读取波形，可尝试直接播放。</p>';}
}
window.addEventListener('resize',()=>drawWave(version()));
function compareDialog(){stop();updatePlayback();const vs=compare.map(id=>sound().versions.find(v=>v.id===id));showDialog('听听，哪一版更合适',`<p>每版从开头试听，一次只播放一个。不同长度的版本也可以比较。</p><div class="compare-grid">${vs.map((v,i)=>`<article><span class="compare-letter">${i?'B':'A'}</span><h3>V${v.number}</h3><p>${esc(v.prompt)}</p><p class="subtle">${src(v)?time(v.duration):'流程演示 · 无音频'}</p><button class="primary" data-action="compare-play" data-id="${v.id}" ${src(v)?'':'disabled'}>▶ 试听</button><button class="secondary" data-action="choose-compared" data-id="${v.id}">选这版作成品</button></article>`).join('')}</div><p class="field-note">比较原始声音，未做响度归一化或段落对齐。</p>`,true);}
function processDialog(){const v=version();showDialog('继续加工这个版本',`<p>${esc(sound().title)} · V${v.number}。处理结果将保留来源，原版始终不动。</p><div class="process-option"><span>01</span><div><h3>分离音轨</h3><p>把音频中的人声和乐器拆开，分别试听或下载。</p><small>规划能力 · 当前项目尚未接入分轨引擎</small></div><button disabled>分离音轨</button></div><div class="process-option"><span>02</span><div><h3>${v.score||v.imported==='midi'?'使用已有 MIDI':'转成 MIDI'}</h3><p>${v.score||v.imported==='midi'?'已有音符数据，可下载后继续编曲。':'识别单条音轨的音高和节奏；复杂混音建议先分轨。'}</p>${v.score?`<a class="text-link" href="${v.score}" download>下载 MIDI ↗</a>`:v.imported==='midi'&&files.has(v.id)?`<a class="text-link" href="${files.get(v.id).url}" download="${esc(v.filename)}">下载导入的 MIDI ↗</a>`:'<small>规划能力 · 当前尚未接入音频转 MIDI</small>'}</div></div><details class="more-settings"><summary>MIDI 详情与合成能力</summary><p>正式产品在这里按需展开音符、乐器和轨道。默认试听页面无需打开钢琴卷帘。</p><p>MIDI 可以驱动乐器音源。歌声合成还需要歌词、音素对齐和歌声模型；普通语音使用 IndexTTS 2.0。歌声合成与语音引擎当前尚未接入。</p></details>`);}
function importDialog(){showDialog('把已有文件放进项目',`<form id="import-form"><label for="import-destination">放到哪里？</label><select id="import-destination"><option value="new">作为一个新声音</option>${project().sounds.map(s=>`<option value="${s.id}" ${s.id===soundId?'selected':''}>${esc(s.title)} · 添加新版本</option>`).join('')}</select><label for="import-kind">作为新声音时的类型</label><select id="import-kind">${Object.entries(kinds).map(([id,label])=>`<option value="${id}">${label}</option>`).join('')}</select><label for="import-file">音频或 MIDI 文件</label><input type="file" id="import-file" accept="audio/*,.mid,.midi" required><p class="field-note">原型只在本页读取文件，不上传。刷新后需重新选择原文件。MIDI 在这里作为参考导入，不会自动合成人声。</p><p id="import-error" role="alert"></p><button class="primary" type="submit">导入</button></form>`);
  $('#import-form').onsubmit=async e=>{e.preventDefault();const f=$('#import-file').files[0];if(!f)return;const midi=/\.(mid|midi)$/i.test(f.name);if(!midi&&!f.type.startsWith('audio/')){$('#import-error').textContent='请选择音频或 MIDI 文件。';return;}let s=project().sounds.find(s=>s.id===$('#import-destination').value);if(!s)s=createSound(project(),{title:f.name.replace(/\.[^.]+$/,''),kind:$('#import-kind').value,duration:'原文件长度'});const v=startVersion(s,`导入：${f.name}`);v.status='done';v.imported=midi?'midi':'audio';v.filename=f.name;v.note=midi?'MIDI 参考 · 尚未合成音频':'导入的音频 · 仅在当前页面可用';v.duration=0;files.set(v.id,{url:URL.createObjectURL(f),file:f});if(!midi){const probe=new Audio(files.get(v.id).url);probe.addEventListener('loadedmetadata',()=>{if(Number.isFinite(probe.duration))v.duration=probe.duration;save();if(versionId===v.id)render();},{once:true});probe.addEventListener('error',()=>toast('浏览器无法播放此音频编码，请换用 WAV 或 MP3。'),{once:true});}soundId=s.id;resetSelection();versionId=v.id;save();dialog.close();render();toast('文件已添加到当前声音。');};
}
function dispatch(action,id){const s=sound(),v=s?.versions.find(v=>v.id===(id??versionId));
  switch(action){
    case 'project':projectId=id;soundId=project().sounds[0]?.id;resetSelection();render();break;
    case 'sound':soundId=id;resetSelection();render();break;
    case 'new-project':showDialog('新建项目',`<form id="project-form"><p>把这次创作的音乐、片段和语音放在一起。</p><label for="project-name">项目名称</label><input id="project-name" required maxlength="120" placeholder="例如：秋日短片配乐" autofocus><div class="dialog-bottom"><button type="button" class="quiet" data-action="close">取消</button><button type="submit" class="primary">创建项目 →</button></div></form>`);$('#project-form').onsubmit=e=>{e.preventDefault();projectId=createProject(state,$('#project-name').value).id;soundId=undefined;resetSelection();save();dialog.close();render();};break;
    case 'new-sound':newSoundDialog();break;
    case 'close':if(dialog.querySelector('[data-action=compare-play]'))stop();dialog.close();updatePlayback();break;
    case 'version':stop();audio.loop=false;versionId=id;render();break;
    case 'play':void play();break;
    case 'loop':audio.loop=!audio.loop;render();break;
    case 'keep':v.kept=!v.kept;save();render();break;
    case 'final':setFinal(s,v.id);save();render();toast(s.finalId?'已选作成品，其他版本仍然保留。':'已取消成品选择。');break;
    case 'filter':filter=id;render();break;
    case 'delete':{stop();deleteVersion(s,v.id);compare=compare.filter(x=>x!==v.id);if(parentId===v.id)parentId=undefined;save();render();toast(`V${v.number} 已移入回收站。`,()=>{restoreVersion(s,v.id);save();render();});break;}
    case 'iterate':parentId=v.id;s.draft=(v.description??v.prompt)+'\n\n我想进一步调整：';s.script=v.script??s.script;save();render();$('#prompt').focus();break;
    case 'retry':s.draft=v.description??v.prompt;s.script=v.script??s.script;parentId=v.parentId&&!s.versions.find(x=>x.id===v.parentId)?.deleted?v.parentId:undefined;save();render();$('#prompt').focus();toast('已恢复这次的创作要求，可调整后重新生成。');break;
    case 'clear-parent':parentId=undefined;render();break;
    case 'cancel':finishVersion(state,projectId,s.id,v.id,'cancelled');save();render();break;
    case 'compare':if(compare.length===2)compareDialog();break;
    case 'compare-play':void play(v);break;
    case 'choose-compared':if(s.finalId!==id)setFinal(s,id);save();stop();versionId=id;dialog.close();render();toast(`V${v.number} 已选作成品。`);break;
    case 'details':showDialog('版本详情',`<dl><dt>版本</dt><dd>${esc(s.title)} · V${v.number}</dd><dt>来源</dt><dd>${v.parentId?`基于 V${s.versions.find(x=>x.id===v.parentId)?.number}`:v.imported?'本地文件导入':'独立尝试'}</dd><dt>创作要求</dt><dd>${esc(v.prompt)}</dd>${v.engine?`<dt>语音引擎</dt><dd>${esc(v.engine)} · 流程演示</dd><dt>参考声音</dt><dd>${esc(v.referenceName)}</dd>`:''}<dt>备注</dt><dd>${esc(v.note)}</dd></dl>`);break;
    case 'process':processDialog();break;
    case 'import':importDialog();break;
    case 'trash':showDialog('回收站',`<p>删除只影响所选版本，不会连带删除基于它创建的版本。恢复后不会自动重新选作成品。</p>${project().sounds.flatMap(s=>s.versions.filter(v=>v.deleted).map(v=>`<div class="trash-row"><span>${esc(s.title)} · V${v.number}</span><button data-action="restore" data-id="${v.id}">恢复</button></div>`)).join('')||'<p class="empty-versions">这里还没有删除的版本。</p>'}`);break;
    case 'restore':{const target=project().sounds.find(s=>s.versions.some(v=>v.id===id));restoreVersion(target,id);save();dialog.close();render();toast('版本已恢复。');break;}
    case 'deliverables':showDialog('项目成品',`<p>每个声音选一版作为成品。一个项目可以交付多个声音。</p>${project().sounds.filter(s=>s.finalId).map(s=>{const v=s.versions.find(v=>v.id===s.finalId);return `<div class="deliverable"><span class="sound-icon ${s.kind}">${icon[s.kind]}</span><div><h3>${esc(s.title)}</h3><p>${kinds[s.kind]} · V${v.number}${src(v)?' · '+time(v.duration):' · 演示结果，无音频'}</p></div>${src(v)?`<a class="secondary" href="${esc(src(v))}" download>下载${v.duration===20?'原始整曲':'音频'}</a>`:''}</div>`;}).join('')||'<p class="empty-versions">还没有成品。试听满意后，点击「选作成品」。</p>'}`);break;
    case 'copy-brief':navigator.clipboard.writeText($('#agent-brief').value).then(()=>toast('创作要求已复制。')).catch(()=>{$('#agent-brief').select();toast('请复制已选中的创作要求。');});break;
    case 'about':showDialog('关于这个原型','<p>这是声音优先的交互设计提案，尚未替换现有工作台。示例音乐使用项目已有的《雨巷来信》两版 WAV。</p><p>项目、声音、版本、灵感标记、成品选择和回收站保存在独立的浏览器原型数据中。演示生成不会调用模型；分轨、音频转 MIDI、TTS 和歌声合成尚未接入。</p><p>可验证的重点是：你是否始终知道自己在做哪个声音、听哪个版本，以及下一步可以做什么。</p>');break;
  }
}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b&&!b.disabled)dispatch(b.dataset.action,b.dataset.id);});
document.addEventListener('change',e=>{if(e.target.matches('[data-compare]')){const id=e.target.dataset.compare;if(e.target.checked){if(compare.length===2){e.target.checked=false;toast('一次比较两版，请先取消其中一版。');return;}compare.push(id);}else compare=compare.filter(x=>x!==id);render();}});
dialog.addEventListener('close',()=>{if(dialog.querySelector('[data-action=compare-play]'))stop();updatePlayback();});
resetSelection();save();render();
